(function () {
  'use strict';
  // Bank reconciliation, worked in whole cents so sums never drift:
  //   adjusted bank balance     = statement ending balance + deposits in transit - outstanding checks
  //   adjusted register balance = register balance - unrecorded fees + unrecorded interest
  //   difference                = adjusted bank - adjusted register (0 means balanced)
  // Checked under Node (scratchpad/tests/b7basic/cb_test.js): the default example (2,450.00 + 300.00 -
  // 125.00 - 62.40 = 2,562.60; register 2,567.60 - 5.00 fee = 2,562.60) balances to 0.00; amounts like
  // 0.10 + 0.20 reconcile exactly; a 54.20 / 45.20 transposition gives a 9.00 difference (flagged as
  // divisible by 9), and an item entered with the wrong sign gives twice the item (flagged).
  // Item rows are built with DOM methods; user text only ever lives in input values.
  // ---- Reconciliation maths, all in whole cents to avoid floating-point drift ----
  function cents(v) { return Math.round(v * 100); }

  // statement, register, fees, interest: cents. checks, deposits: arrays of cents.
  function reconcile(statement, checks, deposits, register, fees, interest) {
    var sum = function (a) { return a.reduce(function (s, x) { return s + x; }, 0); };
    var out = sum(checks), dep = sum(deposits);
    var adjBank = statement + dep - out;
    var adjReg = register - fees + interest;
    return { checks: out, deposits: dep, adjBank: adjBank, adjReg: adjReg, diff: adjBank - adjReg };
  }

  // Common causes of a difference, given the difference and every item amount (all cents).
  function clues(diff, items) {
    var d = Math.abs(diff), list = [];
    if (d === 0) return list;
    if (items.indexOf(d) !== -1) list.push('The difference equals one of your items. Check whether it was left out of the register, recorded twice, or has already cleared the bank.');
    if (d % 2 === 0 && items.indexOf(d / 2) !== -1) list.push('The difference is exactly twice one of your items. An entry may have been added instead of subtracted (or the reverse).');
    if (d % 9 === 0) list.push('The difference divides evenly by 9, a typical sign of two digits swapped when writing an amount (for example 54.20 entered as 45.20).');
    if (d % 100 === 0 || d < 100) list.push('A round-dollar or cents-only difference often comes from a simple addition or subtraction slip in the register.');
    list.push('Compare each cleared item on the statement with your register, and look for fees, interest or automatic payments you haven’t recorded.');
    return list;
  }

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var counters = { chk: 0, dep: 0 };

  function fromCents(c) { return money.format(c / 100); }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function el(tag, className, text) {
    var e = document.createElement(tag);
    if (className) e.className = className;
    if (text) e.textContent = text;
    return e;
  }

  // Builds one item row with DOM methods; user text is only ever held in input values.
  function addRow(kind, desc, amount) {
    var list = document.getElementById(kind === 'chk' ? 'cbChecks' : 'cbDeposits');
    counters[kind]++;
    var n = counters[kind];
    var noun = kind === 'chk' ? 'Check or withdrawal' : 'Deposit';
    var row = el('div', 'grid grid-cols-[minmax(0,1fr)_auto] items-center gap-2 sm:grid-cols-[minmax(0,1fr)_minmax(0,9rem)_auto]');
    row.setAttribute('data-row', kind);

    var d = el('input', 'form-control col-span-2 sm:col-span-1');
    d.type = 'text'; d.id = 'cb' + (kind === 'chk' ? 'Chk' : 'Dep') + 'Desc' + n; d.maxLength = 40; d.autocomplete = 'off';
    d.placeholder = kind === 'chk' ? 'Check # or payee' : 'Description';
    d.setAttribute('aria-label', noun + ' ' + n + ' description (optional)');
    d.value = desc || '';

    var group = el('div', 'input-group');
    var a = el('input', 'min-w-0 flex-1 bg-transparent px-3 text-[15px] tabular-nums text-ink focus:outline-none');
    a.type = 'number'; a.id = 'cb' + (kind === 'chk' ? 'Chk' : 'Dep') + 'Amt' + n; a.min = '0'; a.step = '0.01'; a.inputMode = 'decimal';
    a.setAttribute('aria-label', noun + ' ' + n + ' amount');
    a.setAttribute('data-amount', kind);
    a.value = amount === undefined || amount === '' ? '' : String(amount);
    group.appendChild(el('span', 'input-affix', '$'));
    group.appendChild(a);

    var remove = el('button', 'button-secondary h-11 px-3 text-sm', 'Remove');
    remove.type = 'button';
    remove.setAttribute('aria-label', 'Remove ' + noun.toLowerCase() + ' ' + n);
    remove.addEventListener('click', function () {
      row.remove();
      update();
    });

    row.appendChild(d); row.appendChild(group); row.appendChild(remove);
    list.appendChild(row);
    return a;
  }

  function amounts(kind) {
    var bad = false, list = [];
    Array.prototype.forEach.call(document.querySelectorAll('input[data-amount="' + kind + '"]'), function (input) {
      if (input.value.trim() === '') { if (input.validity && input.validity.badInput) bad = true; return; }
      var v = parseFloat(input.value);
      if (isNaN(v) || v < 0) { bad = true; return; }
      if (v > 0) list.push(cents(v));
    });
    return { list: list, bad: bad };
  }

  function update() {
    var error = document.getElementById('cbError');
    var st = parseFloat(document.getElementById('cbStatement').value),
        reg = parseFloat(document.getElementById('cbRegister').value),
        fees = parseFloat(document.getElementById('cbFees').value),
        intr = parseFloat(document.getElementById('cbInterest').value);
    if (isNaN(fees)) fees = 0;
    if (isNaN(intr)) intr = 0;
    var chk = amounts('chk'), dep = amounts('dep');
    var msg = '';
    if (isNaN(st) || isNaN(reg)) msg = 'Enter both the statement ending balance and your register balance.';
    else if (chk.bad || dep.bad || fees < 0 || intr < 0) msg = 'Item amounts, fees and interest must be numbers of 0 or more.';
    else if (Math.abs(st) > 1e12 || Math.abs(reg) > 1e12) msg = 'Enter balances under one trillion dollars.';
    error.textContent = msg; error.hidden = !msg;
    var status = document.getElementById('cbStatus'), cluesList = document.getElementById('cbClues');
    while (cluesList.firstChild) cluesList.removeChild(cluesList.firstChild);
    if (msg) {
      ['cbDiff', 'cbAdjBank', 'cbAdjReg', 'cbOutStatement', 'cbOutDeposits', 'cbOutChecks', 'cbOutAdjBank', 'cbOutRegister', 'cbOutFees', 'cbOutInterest', 'cbOutAdjReg']
        .forEach(function (id) { set(id, '–'); });
      status.hidden = true; cluesList.hidden = true;
      return;
    }
    var r = reconcile(cents(st), chk.list, dep.list, cents(reg), cents(fees), cents(intr));
    set('cbDiff', fromCents(r.diff));
    set('cbAdjBank', fromCents(r.adjBank));
    set('cbAdjReg', fromCents(r.adjReg));
    set('cbOutStatement', fromCents(cents(st)));
    set('cbOutDeposits', fromCents(r.deposits) + ' (' + dep.list.length + ')');
    set('cbOutChecks', fromCents(r.checks) + ' (' + chk.list.length + ')');
    set('cbOutAdjBank', fromCents(r.adjBank));
    set('cbOutRegister', fromCents(cents(reg)));
    set('cbOutFees', fromCents(cents(fees)));
    set('cbOutInterest', fromCents(cents(intr)));
    set('cbOutAdjReg', fromCents(r.adjReg));

    status.hidden = false;
    if (r.diff === 0) {
      status.className = 'callout callout-success mt-5 text-[15px]';
      status.textContent = 'Your checkbook is balanced. The adjusted bank and register balances match to the cent.';
      cluesList.hidden = true;
    } else {
      status.className = 'callout callout-warning mt-5 text-[15px]';
      status.textContent = r.diff > 0
        ? 'Not balanced: the bank shows ' + fromCents(r.diff) + ' more than your register. Something may be missing from your register (a deposit or interest), or a withdrawal may be recorded too high.'
        : 'Not balanced: your register shows ' + fromCents(-r.diff) + ' more than the bank. A withdrawal, fee or outstanding check may be missing, or a deposit may be recorded too high.';
      clues(r.diff, chk.list.concat(dep.list)).forEach(function (text) { cluesList.appendChild(el('li', '', text)); });
      cluesList.hidden = false;
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('cbForm');
    if (!form) return;
    addRow('chk', '1043', '125.00');
    addRow('chk', '1045', '62.40');
    addRow('chk', '', '');
    addRow('dep', 'Paycheck', '300.00');
    addRow('dep', '', '');
    document.getElementById('cbAddCheck').addEventListener('click', function () { addRow('chk', '', '').focus(); });
    document.getElementById('cbAddDeposit').addEventListener('click', function () { addRow('dep', '', '').focus(); });
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
